import * as React from "react"
import Layout from "../components/layout"
import { graphql } from "gatsby"
import Seo from "../components/seo"

export const Head = () => <Seo title="Política de privacidad" noindex={true} />


const PageTemplate = ({ data }) => {

  let string_content = ""
  data.content.nodes.forEach(item => {
    string_content = string_content + item.content
  })
  return (
    <Layout>
      <section className="construct-contact-page-area section_50">

        <div
          className="container"
          dangerouslySetInnerHTML={{ __html: string_content }}
        ></div>
      </section>
    </Layout>
  )
}

export const query = graphql`
  {
    content: allPoliticaPrivacidadJson {
      nodes {
        content
      }
    }

    privacidad: allPagesJson(
      filter: { idPage: { eq: "politica-privacidad" } }
    ) {
      nodes {
        idPage
        content {
          category
          description
          title
        }
      }
    }
  }
`

export default PageTemplate
